\item[(d)] it obeys the geometrical optics reflection law 
\begin{equation}
\dot{\gamma}_{x,\theta,j+1}(0) = \dot{\gamma}_{x,\theta,j}(L_{j}) - 2\left\langle \nu(\gamma_{x,\theta,j}(L_{j})),\dot{\gamma}_{x,\theta,j}(L_{j}) \right\rangle \nu(\gamma_{x,\theta,j}(L_{j})), \,1 \leq j \leq N.
\end{equation}
\end{enumerate}
Here $L_{j}$ denotes the length of $\gamma_{x,\theta,j}$ and the subscripts refer to the fact that $(\gamma_{x,\theta}(0), \dot{\gamma}_{x,\theta}(0)) = (x,\theta)$.

We use the notation $T:\Gamma_{-} \to \Gamma_{-}$ to denote the billiard map mapping a vector $(x,\theta) \in \Gamma_{-}$ to $(x',\theta') \in \Gamma_{-}$, where $x'$ is the intersection point of the geodesic $\gamma_{x,\theta}$ with $\partial \Omega$, and $\theta'$ is the reflected direction. We use the maps $\pi_{1},\pi_{2}$ to denote the projections $\Gamma_{-} \to \partial \Omega$ and $\Gamma_{-} \to \mathbb{S}^{n-1}$, respectively. Also $\tau_{\pm}(x,\theta) = \min \{ t \geq 0 \, | \, x + t\theta \in \partial \Omega\}$ are the positive and negative travel times from a given unit tangent vector $(x,\theta) \in S\Omega$, and $N(x,\theta)$ for $(x,\theta) \in \Gamma_{-}(E)$ will denote the number of reflections of the given trajectory before intersecting $E$. We use the notation $g^{\#}(x,\theta) := g(x + \tau_{-}(x,\theta)\theta, \theta)$ to denote the extension of a function $g$ on $\Gamma_{-}$ to $\Omega \times \mathbb{S}^{n-1}$. 

\subsection{Unattenuated Case}
First we consider the unattenuated broken ray transform $I_{0,E}$ with respect to the accessible set $E$, so as not to be distracted by technicalities. The operator $I_{0,E}:L^{2}(\Omega) \to L^{2}(\Gamma_{-}, d\Sigma)$, where $d\Sigma = |\nu(x) \cdot \theta|\, dS(x)\, d\theta$ is the standard measure on $\Gamma_{-}$, is defined by
\begin{equation}
I_{0, E}f(\gamma_{x,\theta}) = I_{0, E}f(x,\theta) := \sum_{j=0}^{N(x,\theta)}\int_{\rn{+}} f(\pi_{1} \circ T^{j}(x,\theta) + t \pi_{2}\circ T^{j}(x,\theta))\,dt. \label{forwardoperator}
\end{equation}

The weight functions $w_{j}$ on $S\Omega$ are given by
\begin{align}
w_{j}(y,\eta) & = \exp\left( -\sum_{m=0}^{j-1} \int_{\mathbb{R}_{+}}\sigma( z_{m-j}+\tau \theta_{m-j},\theta_{m-j})\,d\tau\right) \exp\left( -\int_{\mathbb{R}_{+}}\sigma(y - \tau \eta, \eta)\,d\tau \right)\notag\\
& = \exp\left( -\sum_{m=1}^{j} \int_{\mathbb{R}_{+}}\sigma( z_{-m}+\tau \theta_{-m},\theta_{-m})\,d\tau\right) \exp\left( -\int_{\mathbb{R}_{+}}\sigma(y - \tau \eta, \eta)\,d\tau \right)\notag
\end{align}
It is important to note that because $\sigma$ vanishes near $\partial \Omega$, the weight functions $w_{j}$ are smooth. The reason is that we can circumscribe $\Omega$ with the ball $B = B\left( \left( \frac{1}{2}, \frac{1}{2} \right), \frac{\sqrt{2}}{2} \right)$ and then replace $z_{m-j}(y,\eta) = \pi_{1} \circ T^{m-j}(y+ \tau_{-}(y,\eta)\eta,\eta)$ with the last point of $\partial B$ that intersects the line $z_{m-j}(y,\eta) + t\theta_{m-j}(y,\eta)$ for $t \leq 0$. This point is smoothly dependent on $(y,\eta) \in \Omega \times \mathbb{S}^{n-1}$. 


Just as we could rewrite the unattenuated broken ray transform as a standard X-ray transform for the augmented function $\widetilde{f}$, we can do the same for the attenuated case. First we define an extension of $\sigma$ on $\widetilde{\Omega}\times \mathbb{S}^{1}$ by
\begin{equation}
\widetilde{\sigma}(x,\theta) = \left\{ \begin{array}{ll}
\sigma( R_{l_{1},l_{2}}^{-1}(x), S_{l_{1},l_{2}}^{-1}(\theta)) & \textrm{ for }x \in [l_{1},l_{1}+1] \times [l_{2},l_{2}+1],\\
&  \quad (l_{1},l_{2}) \in \mathbb{Z}^{2}.
\end{array}\right.
\end{equation}
Then $\widetilde{w}(x,\theta) := \exp\left( -\int_{0}^{L(\gamma_{x,-\theta})}\widetilde{\sigma}(x-\tau\theta,\theta)\,d\tau\right)$ is the associated weight for $(x,\theta) \in \widetilde{\Omega} \times \mathbb{S}^{1}$. We've used the notation $L(\gamma_{x,-\theta})$ to mean the length of the half broken ray with initial condition $(x,-\theta)$ before hitting some copy of $E$ in $\widetilde{\Omega}$. Obviously, $\sigma \equiv 0$ implies that $w \equiv 1$, which is analytic. However, for general $\sigma$ that are analytic on $\Omega$, it is not generally true that $\widetilde{\sigma}$ is analytic. In fact, it is easy to see that $\widetilde{\sigma}$ has symmetries somewhat like that of a doubly periodic function, which if analytic would necessarily be constant (the Weierstrass $\wp$-function is doubly periodic but has poles). This is the reason why we start with the case that the weight function is identically $1$ (equivalently $\sigma = 0$) and then prove stability for $C^{2}$ perturbations of $\sigma$ that remain $0$ in a neighborhood of $\partial \Omega$.

For the purposes of this work, we need $\alpha I_{\sigma, E}: L^{2}(\Omega, \mathbb{S}^{n-1}) \to L^{2}(\Gamma_{-}, d\Sigma)$ to be bounded, where $\alpha$ is a smooth cutoff function which is supported only for broken rays that have at most $N_{max} \geq 0$ reflections. 
\begin{lemma}Let $\alpha \in C_{0}^{\infty}(\Gamma_{-})$ and suppose all regular broken rays in $\mathrm{supp}(\alpha)$ have $\leq N_{max} \in \mathbb{N}$ reflections. Then $I_{\sigma, E}:L^{2}(\Omega, \mathbb{S}^{n-1}) \to L^{2}(\Gamma_{-}, d\Sigma)$ is bounded.\end{lemma}
\begin{proof}
First we recall an identity from \cite{inversesource} which asserts that for any function $f \in L^{2}(\Omega, \mathbb{S}^{n-1})$, we have
\begin{equation*}
\int_{\Gamma_{-}}\int_{\mathbb{R}_{+}} f(x+t\theta, \theta)\,dt\,d\Sigma = \int_{\Omega \times \mathbb{S}^{n-1}} f(x,\theta)\,dx\,d\theta.
\end{equation*}

Now observe that
\begin{align*}
\| \alpha I_{\sigma, E} f(x,\theta) \|_{L^{2}(\Gamma_{-})}^{2} & \leq 2 \int_{\Gamma_{-}} |\alpha(x,\theta)|^{2}\sum_{j=0}^{N(x,\theta)}\left| \int_{\mathbb{R}_{+}} [w_{j} f](z_{j}(x,\theta) + t\theta_{j}(x,\theta), \theta_{j}(x,\theta))\,dt \right|^{2} \, d\Sigma\\
&\leq 2 \int_{\Gamma_{-}} \sum_{j=0}^{N_{max}}\left| \int_{\mathbb{R}_{+}} \chi_{[0,\tau_{+}(z_{j},\theta_{j})]}(t)[w_{j} f](z_{j}(x,\theta) + t\theta_{j}(x,\theta), \theta_{j}(x,\theta))\,dt \right|^{2} \, d\Sigma\\
& \leq 2 \int_{\Gamma_{-}} \sum_{j=0}^{N_{max}} \|\chi_{[0,\tau_{+}(z_{j},\theta_{j})]}\|_{L^{2}(\mathbb{R}_{+})}^{2}\|[w_{j}f](z_{j}+t\theta_{j},\theta_{j})\|_{L^{2}(\mathbb{R}_{+})}^{2}\,d\Sigma\\
& \leq 2 \int_{\Gamma_{-}} \sum_{j=0}^{N_{max}} \mathrm{diam}(\Omega)\|f(z_{j}+t\theta_{j},\theta_{j})\|_{L^{2}(\mathbb{R}_{+})}^{2}\,d\Sigma\\
& = 2 \int_{\Gamma_{-}} \sum_{j=0}^{N_{max}} \mathrm{diam}(\Omega)\int_{\mathbb{R}_{+}}|f(z_{j}+t\theta_{j},\theta_{j})|^{2}\,dt\,d\Sigma\\
& = 2 (N_{max}+1)\mathrm{diam}(\Omega)\int_{\Gamma_{-}} \int_{\mathbb{R}_{+}}|f(x+t\theta,\theta)|^{2}\,dt\,d\Sigma\\
& = 2 (N_{max}+1)\mathrm{diam}(\Omega)\|f\|_{L^{2}(\Omega \times \mathbb{S}^{n-1})}^{2}.
\end{align*}
\end{proof}

To formulate a stability estimate, we must first parametrize a family of regular broken rays, having an upper bound on the number of reflections, and whose conormal bundles cover $T^{*}\Omega$. Fix a positive $N_{max} \in \mathbb{N}$. For each regular broken ray $\gamma_{x_{0},\theta_{0}}$ with $N(x_{0},\theta_{0}) \leq N_{max}$, let $(l_{1},l_{2})$ be it's reflection signature on $\widetilde{\Omega}$. If $\gamma_{x_{0},\theta_{0}}$ has no corner points, then find a maximal connected neighborhood $U \subset \Gamma_{-}(E)$ containing $(x_{0},\theta_{0})$ such that all broken rays with initial data in $U$ are regular, have no corner points, and have the same reflection signature $(l_{1},l_{2})$ (See Figure \ref{fig:beam}). In particular, $U$ itself contains no corner points. We then choose a smooth cutoff function $\alpha_{k}$ on $\Gamma_{-}$ that is equal to $1$ on a compact subset of $U$ and vanishes outside of $U$. 

\begin{figure}
\centering
\def \svgwidth{0.6\columnwidth}

\caption{A typical beam of unfolded broken rays which follow the same reflection sequence before hitting $E$. The beam terminates in the part of $\widetilde{\Omega}$ with reflection signature $(h_{4},v_{4}) = (2,2)$.\label{fig:beam}}
\end{figure}

If $x_{0}$ is a corner point, then we consider all directed lines $\mathcal{L} = \{(x+t\theta,\theta) \, | \, t \in \mathbb{R}\}$ for $(x,\theta)$ in some neighborhood of $(x_{0},\theta_{0})$ such that $N(x,\theta)$ is constant. Then take the intersection of $\mathcal{L}$ with the ball $B = \left( \left( \frac{1}{2}, \frac{1}{2}\right), \frac{\sqrt{2}}{2} \right)$ of radius $\frac{\sqrt{2}}{2}$ whose boundary $\partial B$ circumscribes $\Omega$. We then define a smooth function $\alpha$ on $\partial B \times \mathbb{S}^{1}$ supported in $\partial B \times \mathbb{S}^{1} \cap \mathcal{L}$. We may then extend $\alpha$ to $\rn{2} \times \mathbb{S}^{1}$ to be constant on all directed lines $(x+t\theta, \theta)$. Its restriction to $\Gamma_{-}(\partial \Omega)$ is the cutoff we seek. We will treat the case that $\gamma_{x_{0},\theta_{0}}$ contains an additional corner point in \S \ref{sec:corners}. 

Let $\alpha = \sum_{k=1}^{N_{\alpha}}\alpha_{k}$ be a sum of smooth cutoff functions on $\Gamma_{-}(E)$ in the sense of the previous paragraph, and consider the regularized operator
\begin{equation}
I_{\sigma,E,\alpha} := \sum_{k=1}^{N_{\alpha}}\alpha_{k} I_{\sigma,E}.
\end{equation}

Then
\begin{equation}
N_{\sigma, E, \alpha} := I_{\sigma, E,\alpha}^{*} I_{\sigma, E, \alpha} =  \sum_{k_{1}=1,k_{2}=1}^{N_{\alpha}}I_{\sigma,E}^{*}\alpha_{k_{1}}\alpha_{k_{2}}I_{\sigma, E}.
\end{equation}

We also define the \textit{microlocally visible set} by
\begin{equation}
\mathcal{M}' := \{ (z,\xi) \in T^{*}\Omega \, | \, (z,\xi) \in N^{*}\gamma_{x,\theta} \textrm{ for some }(x,\theta) \textrm{ with }\alpha(x,\theta) > 0\}.
\end{equation}

Thus there exists a classical pseudo differential operator $Q$ in $\Omega$ of order $1$ such that
\begin{equation}
QN_{\sigma, E,\alpha}f = f + QN_{\sigma,E,\alpha,reflect}f + S_{1}
\end{equation}
for any $f \in \mathcal{D}'(K)$, where $S_{1}$ is an operator with $C_{0}^{\infty}(\Omega \times \Omega)$ Schwartz kernel. \label{prop:normaldecomposition}\end{proposition}

\subsection{Computing the Normal Operator\label{sec:normaloperatorcompute}}
Recall that given $j \in \mathbb{Z}$ we have defined the variables $z_{j},\theta_{j}$ depending on $x \in \Omega$, $\theta \in \mathbb{S}^{1}$ by
\begin{equation*}
(z_{j}, \theta_{j}) := T^{j}(x+\tau_{-}(x,\theta)\theta,\, \theta)
\end{equation*}

The adjoint to $\alpha I_{\sigma,E}$ can be computed as follows:
\begin{align}
& \quad \int_{\Gamma_{-}}\alpha(x,\theta) [I_{\sigma,E}f](x,\theta) g(x,\theta)\,d\Sigma \label{eq:adjointcomputation}\\
& = \int_{\Gamma_{-}}\alpha(x,\theta) g(x,\theta) \sum_{j=0}^{N}\int_{\rn{+}} w_{j}(z_{j}+t\theta_{j},\theta_{j})f(z_{j} + t \theta_{j})|\nu(x) \cdot \theta|\,dt\,dS(x)\,d\theta \notag
\end{align}

For each $j$ we make the change of variables $(x,\theta,t) \mapsto (y,\eta)$ where $(y,\eta) := (z_{j}(x,\theta)+t\theta_{j}(x,\theta), \theta_{j}(x,\theta))$. Thus
\begin{align}
(x,\theta) & = (z_{-j}(y,\eta), \theta_{-j}(y,\eta))\notag\\
t & = -\tau_{-}(y,\eta).
\end{align}

