I_{0, E}f(\gamma_{x,\theta}) = I_{0, E}f(x,\theta) := \sum_{j=0}^{N(x,\theta)}\int_{\rn{+}} f(\pi_{1} \circ T^{j}(x,\theta) + t \pi_{2}\circ T^{j}(x,\theta))\,dt. \label{forwardoperator}
\end{equation}

