I_{\sigma,E,\alpha}f(x,\theta) := \sum_{k=1}^{N_{\alpha}}\alpha_{k}(x,\theta)I_{\sigma,E}f(x,\theta), \quad (x,\theta) \in \Gamma_{-}(E).
\end{equation}

