\begin{remark*}
One simple example of what $\mathcal{M}$ looks like is the case when $E$ contains two adjacent edges of the square $\Omega = (0,1)^2$. Then $\mathcal{M} = \Omega$.

Similarly, if $\Omega = \{x \in \rn{n} \, | \, |x| \leq 1 \}$, then for $E$ containing a hemisphere we have $\mathcal{M} = \Omega$.

In general, if $E = \bigcup_{j}E_{j}$ is a union of connected open subsets $E_{j}$ of the boundary, then we always have $\bigcup_{j} \mathrm{ch}(E_{j})\subset \mathcal{M}$, where $\mathrm{ch}$ denotes the closed convex hull. However, this is the part of $\mathcal{M}$ that is attributed to only ballistic (unreflected) X-rays.
\end{remark*}

\begin{equation}
\widetilde{f}(x) = \left\{ \begin{array}{ll}
f(R_{l_{1},l_{2}}^{-1}(x)) & \textrm{ if }x \in [l_{1},l_{1}+1] \times [l_{2},l_{2}+1]\\
& (l_{1},l_{2}) \in \mathbb{Z}^{2},
\end{array}\right.
\end{equation}

\begin{equation*}
\int_{\Gamma_{-}}\int_{\mathbb{R}_{+}} f(x+t\theta, \theta)\,dt\,d\Sigma = \int_{\Omega \times \mathbb{S}^{n-1}} f(x,\theta)\,dx\,d\theta.
\end{equation*}

\begin{equation*}
U = \{x = (\theta^{1}, t) \, | \, |\theta^{1}| < \epsilon, \, l^{-} < t < l^{+} \} \subset \widetilde{\Omega}.
\end{equation*}

\begin{equation*}
\left| \frac{\partial y}{\partial \eta \partial t} \right| = |(-1)^{l_{1}}(l_{1} -x^{1})\sec{\eta} + t | = |\widetilde{y}-\widetilde{z}|\left| \frac{\widetilde{y}^{1}-x^{1}}{\widetilde{y}^{1} - l_{1}} \right|
\end{equation*}

\begin{equation*}
\widehat{\eta} = ((-1)^{l_{1}}\cos{\theta},(-1)^{l_{2}}\sin{\theta}) = \frac{1}{|\widetilde{y}-x|}( (-1)^{l_{1}}(\widetilde{y}^{1}- x^{1}), (-1)^{l_{2}}(\widetilde{y}^{2} - x^{2})).
\end{equation*}

\begin{equation*}
\|f\|_{L^{2}(K)} \leq C\|N_{\sigma, E, \alpha}f\|_{H^{1}(\Omega)} + C_{s}\|f\|_{H^{-s}(\Omega)}, \quad \forall s;
\end{equation*}

\begin{equation*}
QN_{\sigma, E, \alpha}f = f + QN_{\sigma, E, \alpha, reflect}f + S_{1}f =: f + S_{2}f.
\end{equation*}

\begin{equation*}
\|f\|_{L^{2}(K)} - C_{s}\|f\|_{H^{-s}(\Omega)} \leq \|QN_{\sigma, E, \alpha}f\|_{L^{2}(K)} \leq C \|f\|_{H^{1}(\Omega)}
\end{equation*}

\begin{equation}
\|N_{\sigma, E, \alpha, ballistic} - N_{\sigma', E, \alpha', ballistic}\|_{H^{1}(\Omega)} \leq C \delta \|f\|_{L^{2}(K)}.
\end{equation}

\begin{equation*}
\|f\|_{L^{2}(K)} \leq C( \| N_{\sigma, E, \alpha}f\|_{H^{1}(\Omega)}  + \|(S_{1} + QN_{\sigma, E, \alpha, reflect})f\|_{L^{2}(\Omega)}).
\end{equation*}

First we recall an identity from \cite{inversesource} which asserts that for any function $f \in L^{2}(\Omega, \mathbb{S}^{n-1})$, we have
\begin{equation*}
\int_{\Gamma_{-}}\int_{\mathbb{R}_{+}} f(x+t\theta, \theta)\,dt\,d\Sigma = \int_{\Omega \times \mathbb{S}^{n-1}} f(x,\theta)\,dx\,d\theta.

Recall that given $j \in \mathbb{Z}$ we have defined the variables $z_{j},\theta_{j}$ depending on $x \in \Omega$, $\theta \in \mathbb{S}^{1}$ by
\begin{equation*}
(z_{j}, \theta_{j}) := T^{j}(x+\tau_{-}(x,\theta)\theta,\, \theta)
\end{equation*}
Notice that $(z_{0},\theta_{0}) = (x + \tau_{-}(x,\theta)\theta, \theta)$. For now, we will only assume that the domain $\Omega$ is an open subset of $\rn{n}$ with piecewise smooth, convex boundary. In \S \ref{sec:normalsimplify} and beyond we then work specifically with the square $(0,1) \times (0,1)$.

Recall that $N_{\sigma,E,\alpha} = N_{\sigma, E, \alpha, ballistic} + N_{\sigma, E, \alpha, reflect}$, where $N_{\sigma, E, \alpha, ballistic}$ is a weakly singular integral operator with smooth kernel and $N_{\sigma, E, \alpha, reflect}$ is smoothing. By the discussion in the proof of Proposition 4 of \cite{xraygeneric}, we have 
\begin{equation}
\|N_{\sigma, E, \alpha, ballistic} - N_{\sigma', E, \alpha', ballistic}\|_{H^{1}(\Omega)} \leq C \delta \|f\|_{L^{2}(K)}.
\end{equation}
Similarly, the Schwartz kernels of $N_{\sigma, E, \alpha, reflect}$ depend smoothly on $\sigma$ and $\alpha$ (see (\ref{eq:normalreflectedterm}) and (\ref{eq:normalreflectbigkahuna})), so the same estimate holds for this term. The completes the proof.
\end{proof}

Thus we have an integrand involving $f(z(x,\eta) + t\widehat{\eta})$, where $\widehat{\eta} = (\cos{\eta},\sin{\eta})$. The next step is to make the substitution $y = z(x,\eta) + t\widehat{\eta}$ (see Figure \ref{fig:substitution}). We compute it's Jacobian determinant to be
\begin{align}
\left| \frac{\partial y}{\partial \eta \partial t} \right| & = |(-1)^{l_{2}}(l_{2}-x^{2})\csc{\eta} + t| = |(l_{2}-x^{2})\csc{\theta} + t| = |\widetilde{y}-\widetilde{z}|\left| \frac{l_{2}-x^{2}}{\widetilde{y}^{2} - \widetilde{z}^{2}} + 1 \right|\notag\\
& = |\widetilde{y}-\widetilde{z}|\left| \frac{\widetilde{y}^{2}-x^{2}}{\widetilde{y}^{2} - l_{2}} \right|
\end{align}
if $z(x,\eta)$ is given by (\ref{eq:zxeta1}). Similarly, we obtain
\begin{equation*}
\left| \frac{\partial y}{\partial \eta \partial t} \right| = |(-1)^{l_{1}}(l_{1} -x^{1})\sec{\eta} + t | = |\widetilde{y}-\widetilde{z}|\left| \frac{\widetilde{y}^{1}-x^{1}}{\widetilde{y}^{1} - l_{1}} \right|
\end{equation*}
when $z(x,\eta)$ is given by (\ref{eq:zxeta2}). Here we've used the fact that $\sec{\eta} = (-1)^{l_{1}}\sec{\theta}$ and $\csc{\eta} = (-1)^{l_{2}} \csc{\theta}$. In order to fully carry out the substitution in the integral, we need to write $z$ as a function of $x$ and $y$. We will need the auxiliary equation
\begin{equation}
(\widetilde{y} - \widetilde{z}) \cdot (\widetilde{z} - x)^{\perp} = 0,
\end{equation}
which is a consequence of the reflection law. In the case where $\widetilde{z}^{2}$ is undetermined, we have $\widetilde{z}^{1} = l_{1}$ and then
\begin{equation}
\widetilde{z}^{2} - \widetilde{y}^{2} = \frac{(\widetilde{y}^{2}-x^{2})(l_{1} - \widetilde{y}^{1})}{\widetilde{y}^{1} - x^{1}}.
\end{equation}
Similarly, if $\widetilde{z}^{1}$ is undetermined then
\begin{equation}
\widetilde{z}^{1} - \widetilde{y}^{1} = \frac{(\widetilde{y}^{1} - x^{1})(l_{2} - \widetilde{y}^{2})}{\widetilde{y}^{2} - x^{2}}.
\end{equation}

Altogether, we obtain that $N_{\sigma, E,\alpha, reflect}f(x)$ consists of a sum of terms of the form
\begin{equation}
\int_{\rn{2}} |\alpha_{k}(T^{-j_{2}}(y + \tau_{-}(y,\widehat{\eta})\widehat{\eta}, \widehat{\eta}))|^{2} w_{j_{1}}\left( x,\frac{\widetilde{y}-x}{|\widetilde{y}-x|} \right) w_{j_{2}}\left(y, \widehat{\eta}\right)f\left(y\right)\, \frac{dy}{|\widetilde{y} -x|}.\label{eq:normalreflectedterm}
\end{equation}

Unattenuated Case
First we consider the unattenuated broken ray transform $I_{0,E}$ with respect to the accessible set $E$, so as not to be distracted by technicalities. The operator $I_{0,E}:L^{2}(\Omega) \to L^{2}(\Gamma_{-}, d\Sigma)$, where $d\Sigma = |\nu(x) \cdot \theta|\, dS(x)\, d\theta$ is the standard measure on $\Gamma_{-}$, is defined by
\begin{equation}
I_{0, E}f(\gamma_{x,\theta}) = I_{0, E}f(x,\theta) := \sum_{j=0}^{N(x,\theta)}\int_{\rn{+}} f(\pi_{1} \circ T^{j}(x,\theta) + t \pi_{2}\circ T^{j}(x,\theta))\,dt. \label{forwardoperator}
\end{equation}
for all regular broken rays $\gamma_{x,\theta}$. Here 
\begin{equation}
(z_{j}(x,\theta),\theta_{j}(x,\theta)) = T^{j}(x+\tau_{-}(x,\theta)\theta,\theta), \quad (x,\theta) \in S\Omega. \label{eq:zjthetaj}
\end{equation}

Since in general there may be regular broken rays in $\Omega$ with arbitrarily many reflections, we cannot expect for $I_{0,E}:L^{2}(\Omega) \to L^{2}(\Gamma_{-}, d\Sigma)$ to be a bounded operator. Thus, we will instead consider the cutoff operator $\alpha I_{0, E}$, where $\alpha:\Gamma_{-}\to \mathbb{R}$ is a smooth cutoff function supported on some subset of broken rays that have at most $N_{max} \geq 0$ reflections. The boundedness of this cutoff operator, with possible attenuation, will be proved later when we introduce the more general weighted transform.

\begin{remark*}Although general polyhedral domains lack obvious reflection rules at the corners (some authors ignore such trajectories and some define them in terms of limits of regular trajectories, e.g. \cite{eskin}), the special symmetrical nature of the square does give an unambiguous rule for such reflections. But one still runs into the problem that the composite functions $z_{j}(x,\theta), \theta_{j}(x,\theta)$ are not real analytic for $(x,\theta)$ associated with a corner point. One simple, albeit more restrictive route, is to assume that the subset $E$ also includes a small neighborhood of each corner. In that case, all broken rays with corner points are just ballistic X-rays. More generally, one can cut out the rays with corner points from the measurement operator. However, if one assumes the attenuation coefficient to vanish in a neighborhood of the boundary, it is still possible to treat rays with corners as we will discuss later.\end{remark*}

It is easy to see that $N(x,\theta)$ is piecewise constant, which leads to the unfortunate fact that $I_{0, E}$ in general does not preserve the smoothness of a function. Since we are considering a convex domain (flat) in this work, the discontinuities of $N(x,\theta)$ occur only for $(x,\theta) \in \Gamma_{-}(E)$ such that $\gamma_{x,\theta}$ has a reflection occurring at some point in $\partial E$. This is the reason they are not classified as \textit{regular} broken rays. To eliminate such discontinuities introduced by $N(x,\theta)$ we will use a collection of smooth cutoff functions $\alpha_{k}$ on $\Gamma_{-}(E)$ so as to remove the bad parts of $I_{0, E}$. For example, for each point $(x_{0},\theta_{0}) \in \Gamma_{-}(E)$ where $N(x,\theta)$ is continuous (i.e. $\gamma_{x_{0},\theta_{0}}$ and nearby rays do not touch corner points), we may multiply $I_{\sigma, E}$ by a smooth function $\alpha(x,\theta) \equiv 1$ near $(x_{0}, \theta_{0})$ and such that $N(x,\theta) \vert_{\mathrm{supp}(\alpha)}$ is constant. This localized operator will have a constant number of reflections and thus behaves very much like the usual generalized ray transform, which makes it possible to apply the microlocal analytic techniques of \cite{xraygeneric}. Of course, additional care is needed to deal with broken rays that contain corner points, which we discuss later. The central idea is that for fixed $(x,\xi) \in T^{*}\Omega \setminus 0$, any broken ray $\gamma$ passing through $x$ with direction normal to $\xi$ will allow for the detection of $(x,\xi)$ in $\mathrm{WF}_{A}(f)$. From hereon we use the notation $\mathrm{WF}_{A}(f)$ to denote the analytic wavefront set of $f$.

The main idea we use in order to apply microlocal analytic techniques to the operator is a well-known method of billiards called path unfolding. Essentially, we can unfold any broken ray in $\Omega$ into a straight line on a different domain $\widetilde{\Omega}$ defined by reflecting $\Omega$ across each of its edges repeatedly to obtain a tiling of $\rn{2}$. Similarly, we can extend $f$ to a function $\widetilde{f}$ on $\widetilde{\Omega}$ by reflection across $\partial \Omega$. We will use indices $(l_{1},l_{2}) \in \mathbb{Z}^{2}$ to denote how many horizontal and vertical reflections a given broken ray undergoes on the unfolded domain $\widetilde{\Omega}$ before returning to the set $E$. We call this the \textit{reflection signature} of a path. For example, $(-1,2)$ indicates $1$ reflection to the left and $2$ reflections upwards. The following transformations and their respective inverses will be useful when translating between vectors on
$T\Omega$ and $T \widetilde{\Omega}$. Given a reflection signature $(l_{1},l_{2})$, we can compute the reflected version of a point $w \in \Omega$ by
\begin{align}
\widetilde{w} = R_{l_{1},l_{2}}(w) & = \left( l_{1} + \frac{1 - (-1)^{l_{1}}}{2} + (-1)^{l_{1}}w_{1}, l_{2} + \frac{1 - (-1)^{l_{2}}}{2} + (-1)^{l_{2}}w_{2} \right)\\
w = R_{l_{1},l_{2}}^{-1}(\widetilde{w}) & = \left( (-1)^{l_{1}+1}l_{1} + \frac{1-(-1)^{l_{1}}}{2} + (-1)^{l_{1}}\widetilde{w}_{1}, \, (-1)^{l_{2}+1}l_{2} + \frac{1-(-1)^{l_{2}}}{2} + (-1)^{l_{2}}\widetilde{w}_{2} \right).
\end{align}
Similarly, given an angle $\theta$, $S_{l_{1},l_{2}}(\theta)$ is the angle after an $(l_{1},l_{2})$ reflection. 
\begin{align}
\eta = S_{l_{1},l_{2}}(\theta) &= (-1)^{l_{1}+l_{2}}\theta + \frac{\pi}{2}\left[ 1 - (-1)^{l_{1}} \right]\\
\theta = S_{l_{1},l_{2}}^{-1}(\eta) & = (-1)^{l_{2}}\left( (-1)^{l_{1}} \eta + \frac{1-(-1)^{l_{1}}}{2}\pi \right).
\end{align}
Such formulas can be verified with straightforward geometry. Using this notation, we have
\begin{equation}
\widetilde{f}(x) = \left\{ \begin{array}{ll}
f(R_{l_{1},l_{2}}^{-1}(x)) & \textrm{ if }x \in [l_{1},l_{1}+1] \times [l_{2},l_{2}+1]\\
& (l_{1},l_{2}) \in \mathbb{Z}^{2},
\end{array}\right.
\end{equation}
which obviously makes sense even for compactly supported distributions in $\Omega$.

