\end{figure}

If $x_{0}$ is a corner point, then we consider all directed lines $\mathcal{L} = \{(x+t\theta,\theta) \, | \, t \in \mathbb{R}\}$ for $(x,\theta)$ in some neighborhood of $(x_{0},\theta_{0})$ such that $N(x,\theta)$ is constant. Then take the intersection of $\mathcal{L}$ with the ball $B = \left( \left( \frac{1}{2}, \frac{1}{2}\right), \frac{\sqrt{2}}{2} \right)$ of radius $\frac{\sqrt{2}}{2}$ whose boundary $\partial B$ circumscribes $\Omega$. We then define a smooth function $\alpha$ on $\partial B \times \mathbb{S}^{1}$ supported in $\partial B \times \mathbb{S}^{1} \cap \mathcal{L}$. We may then extend $\alpha$ to $\rn{2} \times \mathbb{S}^{1}$ to be constant on all directed lines $(x+t\theta, \theta)$. Its restriction to $\Gamma_{-}(\partial \Omega)$ is the cutoff we seek. We will treat the case that $\gamma_{x_{0},\theta_{0}}$ contains an additional corner point in \S \ref{sec:corners}. 

Let $\alpha = \sum_{k=1}^{N_{\alpha}}\alpha_{k}$ be a sum of smooth cutoff functions on $\Gamma_{-}(E)$ in the sense of the previous paragraph, and consider the regularized operator
\begin{equation}
I_{\sigma,E,\alpha} := \sum_{k=1}^{N_{\alpha}}\alpha_{k} I_{\sigma,E}.
\end{equation}
Then
\begin{equation}
N_{\sigma, E, \alpha} := I_{\sigma, E,\alpha}^{*} I_{\sigma, E, \alpha} =  \sum_{k_{1}=1,k_{2}=1}^{N_{\alpha}}I_{\sigma,E}^{*}\alpha_{k_{1}}\alpha_{k_{2}}I_{\sigma, E}.
\end{equation}
The transpose is taken with respect to the standard measure $|\nu(x) \cdot \theta|\,dS(x)\,d\theta$ on $\Gamma_{-}(E)$. Note that we may as well assume that the $\alpha_{k}$ functions have disjoint support, since it won't change the kind of terms present in the normal operator (if two such cutoff functions $\alpha_{k_{1}}$ and $\alpha_{k_{2}}$ have overlapping support, then their product is also smooth with the supported broken rays localized just as in the previous construction).

We also define the \textit{microlocally visible set} by
\begin{equation}
\mathcal{M}' := \{ (z,\xi) \in T^{*}\Omega \, | \, (z,\xi) \in N^{*}\gamma_{x,\theta} \textrm{ for some }(x,\theta) \textrm{ with }\alpha(x,\theta) > 0\}.
\end{equation}

\begin{remark*}One reason we need to impose an upper bound on the number of reflections is that as $N$ increases, the open level sets of $N(x,\theta)$ shrink in measure to zero. Similarly, the neighborhoods in $\Gamma_{-}$ on which we have constant reflection signature $(l_{1},l_{2})$ become infinitesimal as $|l_{1}|+|l_{2}| \to \infty$. Thus $\alpha$ will not be smooth unless we apply some threshold.\end{remark*}

We have the following stability result analogous to that in \cite{xraygeneric}.
\begin{theorem}
\begin{enumerate}
\item[(a)] Fix $\sigma$ that is $0$ in a neighborhood of $\partial \Omega$, and choose $\alpha \in C^{\infty}(\Gamma_{-})$ as above with reflection threshold $N_{max}$. Fix a set $K \Subset \mathcal{M}$ compactly contained in the visible set $\mathcal{M}$. If $I_{\sigma, E, \alpha}$ is injective on $L^{2}(K)$, then
\begin{equation}
\frac{1}{C}\|f\|_{L^{2}(K)} \leq \|N_{\sigma, E, \alpha}f \|_{H^{1}(\Omega)} \leq C\|f\|_{L^{2}(K)}. \label{eq:stabilityestimate}
\end{equation}
\item[(b)] Let $\alpha^{0}$ be as above related to some fixed $\sigma_{0}$. Assume that $I_{\sigma_{0}, E, \alpha^{0}}$ is injective on $L^{2}(K)$. Then estimate (\ref{eq:stabilityestimate}) remains true for $(\sigma, \alpha)$ in a small $C^{2}$ neighborhood of $(\sigma_{0}, \alpha^{0})$ such that $\sigma \equiv 0$ near $\partial \Omega$, and with a uniform constant $C > 0$.
\end{enumerate}\label{thm:stabilityestimate}
\end{theorem}

Computing the Normal Operator\label{sec:normaloperatorcompute
}
Recall that given $j \in \mathbb{Z}$ we have defined the variables $z_{j},\theta_{j}$ depending on $x \in \Omega$, $\theta \in \mathbb{S}^{1}$ by
\begin{equation*}
(z_{j}, \theta_{j}) := T^{j}(x+\tau_{-}(x,\theta)\theta,\, \theta)
\end{equation*}
Notice that $(z_{0},\theta_{0}) = (x + \tau_{-}(x,\theta)\theta, \theta)$. For now, we will only assume that the domain $\Omega$ is an open subset of $\rn{n}$ with piecewise smooth, convex boundary. In \S \ref{sec:normalsimplify} and beyond we then work specifically with the square $(0,1) \times (0,1)$.

Choose a cutoff function $\alpha(x,\theta)$ on $\Gamma_{-}$ such that $\alpha I_{\sigma, E}$ has a constant number of reflections $N \geq 0$ on its support. Later we will consider broken rays with corner points, but then the number of reflections is not constant, so it must be treated slightly differently. The adjoint to $\alpha I_{\sigma,E}$ can be computed as follows:
\begin{align}
& \quad \int_{\Gamma_{-}}\alpha(x,\theta) [I_{\sigma,E}f](x,\theta) g(x,\theta)\,d\Sigma \label{eq:adjointcomputation}\\
& = \int_{\Gamma_{-}}\alpha(x,\theta) g(x,\theta) \sum_{j=0}^{N}\int_{\rn{+}} w_{j}(z_{j}+t\theta_{j},\theta_{j})f(z_{j} + t \theta_{j})|\nu(x) \cdot \theta|\,dt\,dS(x)\,d\theta \notag
\end{align}

For each $j$ we make the change of variables $(x,\theta,t) \mapsto (y,\eta)$ where $(y,\eta) := (z_{j}(x,\theta)+t\theta_{j}(x,\theta), \theta_{j}(x,\theta))$. Thus
\begin{align}
(x,\theta) & = (z_{-j}(y,\eta), \theta_{-j}(y,\eta))\notag\\
t & = -\tau_{-}(y,\eta).
\end{align}
Intuitively, in moving from $(y,\eta)$ to $\left( z_{-j}(y,\eta), \theta_{-j}(y,\eta) \right)$, we first project from the point $y$ to the boundary along the direction $-\eta$ and then trace backwards along the trajectory for the previous $j$ reflections. We compute
\begin{align}
& \Big(z_{m}(x,\theta) + s\theta_{m}(x,\theta), \theta_{m}(x,\theta)\Big)\notag\\
& = \left(z_{m}\Big(z_{-j}(y,\eta), \theta_{-j}(y,\eta)\Big) + s\theta_{m}\Big(z_{-j}(y,\eta), \theta_{-j}(y,\eta)\Big), \theta_{m}\Big(z_{-j}(y,\eta), \theta_{-j}(y,\eta)\Big)\right)\notag\\
& = (z_{m-j}(y,\eta)+s\theta_{m-j}(y,\eta), \, \theta_{m-j}(y,\eta)).\notag
\end{align}

Given a fixed number of reflections $j$, it is clear that each point $(y, \eta) \in \Omega \times \mathbb{S}^{n-1}$ corresponds to a unique point $(x,\theta) \in \Gamma_{-}$. Thus, the previously described change of variables is a diffeomorphism. The resulting integral is over the domain $\Omega \times \mathbb{S}^{n-1}$.
We have
\begin{align*}
& \sum_{j=0}^{N}\int_{\Omega \times \mathbb{S}^{n-1}}\alpha(z_{-j}(y,\eta), \theta_{-j}(y,\eta))g(z_{-j}(y,\eta), \theta_{-j}(y,\eta))w_{j}(y,\eta)f(y) J_{j}(y,\eta)\,dy\,d\eta,
\end{align*}
where
\begin{equation*}
J_{j}(y,\eta) = \left| \frac{\partial x \partial \theta \partial t}{\partial y \, \partial \eta}\right| |\nu(z_{-j}(y,\eta))\cdot \theta_{-j}(y,\eta)|.
\end{equation*}
Since the billiard map $T$ preserves the symplectic form $|\nu(x) \cdot \theta| dx \wedge d\theta$ on $\Gamma_{-}$, it follows that $J_{j}(y,\eta) = 1$. We stress that this is even true for domains with piecewise smooth boundary as is the case for the square, by measure theoretic arguments (see \cite{serge2} \S 1.7). One can verify that the Jacobian factors above cancel by first making the change of variables $(x,\theta)\to T^{j}(x,\theta)$ in (\ref{eq:adjointcomputation}), using the invariance of the symplectic form $|\nu(x)\cdot \theta| dx\wedge d\theta$ under $T$. Then change to $(y,\eta)$ coordinates on $\Omega \times \mathbb{S}^{n-1}$ using the same approach as in (Theorem 1 (b), \cite{inversesource}). Thus we have
\begin{align}
(\alpha I_{\sigma, E})^{*}g(x) & = \sum_{j=0}^{N}\int_{\mathbb{S}^{n-1}}[\alpha g](z_{-j}(x,\theta), \theta_{-j}(x,\theta)) w_{j}(x,\theta) \,d\theta
\end{align}

We are now ready to compute the normal operator $I_{\sigma,E}^{*}I_{\sigma,E}$. By definition
\begin{align}
& I_{\sigma,E,\alpha}^{*}I_{\sigma,E,\alpha}f(x) \notag\\
& = \sum_{j_{1}=0}^{N}\int_{\mathbb{S}^{n-1}}|\alpha(z_{-j_{1}}(x,\theta), \theta_{-j_{1}}(x,\theta))|^{2}I_{\sigma,E}f(z_{-j_{1}}(x,\theta), \theta_{-j_{1}}(x,\theta))w_{j_{1}}(x,\theta)\, d\theta\notag\\
& = \sum_{j_{1}=0}^{N}\sum_{j_{2}=0}^{N} \int_{\mathbb{S}^{n-1}}\int_{\mathbb{R}_{+}}|\alpha(z_{-j_{1}}(x,\theta), \theta_{-j_{1}}(x,\theta))|^{2} \, w_{j_{1}}(x,\theta)\notag\\
& \quad \cdot w_{j_{2}}(z_{j_{2}-j_{1}}(x,\theta)+t\theta_{j_{2}-j_{1}}(x,\theta), \theta_{j_{2}-j_{1}}(x,\theta)) \, f\left(z_{j_{2}-j_{1}}(x,\theta) + t\theta_{j_{2}-j_{1}}(x,\theta)\right)\,dt\,d\theta \notag\\
& =\sum_{j_{1}=0}^{N}\sum_{j_{2}=0, j_{2} \neq j_{1}}^{N}\int_{\mathbb{S}^{n-1}}\int_{\mathbb{R}_{+}}w_{j_{1}}(x,\theta)\,w_{j_{2}}(z_{j_{2}-j_{1}}(x,\theta) + t\theta_{j_{2}-j_{1}}(x,\theta), \theta_{j_{2}-j_{1}}(x,\theta)) \notag\\
& \quad \cdot |\alpha(z_{-j_{1}}(x,\theta), \theta_{-j_{1}}(x,\theta))|^{2}\, f\left(z_{j_{2}-j_{1}}(x,\theta) + t\theta_{j_{2}-j_{1}}(x,\theta) \right)\,dt\,d\theta\notag\\
& + \sum_{j_{1}=0}^{N}\int_{\mathbb{S}^{n-1}}\int_{\mathbb{R}_{+}}\, w_{j_{1}}(x+t\theta,\theta)w_{j_{1}}(x,\theta) \, |\alpha(z_{-j_{1}}(x,\theta), \theta_{-j_{1}}(x,\theta))|^{2} \, f\left(x +\tau_{-}(x,\theta)\theta + t\theta \right)\,dt\,d\theta \notag\\
& =: N_{\sigma, E, \alpha, reflect}f(x) + N_{\sigma, E, \alpha, ballistic}f(x). \label{eq:normalop}
\end{align}
It follows that the full normal operator $N_{\sigma,E,\alpha}$, corresponding to the partition by smooth cutoff functions $\alpha_{k}$, is given by the sum
\begin{align*}
& N_{\sigma,E,\alpha}f(x) \\
& = \sum_{k=1}^{N_{\alpha}}\sum_{j_{1}=0}^{N_k}\sum_{j_{2}=0}^{N_k}\int_{\mathbb{S}^{n-1}}\int_{\mathbb{R}_{+}} |\alpha_{k}(z_{-j_{1}}, \theta_{-j_{1}})|^{2} w_{j_{1}}\left( x,\theta \right) w_{j_{2}}\left(z_{j_{2}-j_{1}}+ t\theta_{j_{2}-j_{1}}, \theta_{j_{2}-j_{1}}\right)\\
& \cdot f\left(z_{j_{2}-j_{1}}+ t\theta_{j_{2}-j_{1}}\right)\, dt\,d\theta
\end{align*}
We pick off the ballistic terms where $j_{1}=j_{2}$ to decompose $N_{\sigma,E,\alpha}f$ as a sum
\begin{equation*}
N_{\sigma,E,\alpha} = N_{\sigma,E,\alpha, ballistic} + N_{\sigma,E,\alpha,reflect}
\end{equation*}
with
\begin{align*}
& N_{\sigma,E,\alpha,ballistic}f(x)\\
& = \sum_{k=1}^{N_{\alpha}}\sum_{j=0}^{N_{k}}\int_{\mathbb{S}^{n-1}}\int_{\mathbb{R}_{+}} |\alpha_{k}(z_{-j}, \theta_{-j})|^{2} w_{j}\left( x,\theta \right) w_{j}\left(x + (\tau_{-}(x,\theta)+t)\theta, \theta\right)\\
& \qquad \cdot f\left(x + (\tau_{-}(x,\theta)+t)\theta \right)\, dt\,d\theta\\
& = \sum_{k=1}^{N_{\alpha}}\sum_{j=0}^{N_k}\int_{\mathbb{S}^{n-1}}\int_{\mathbb{R}} |\alpha_{k}(z_{-j}, \theta_{-j})|^{2} w_{j}\left( x,\theta \right) w_{j}\left(x + t\theta, \theta\right)f\left(x + t\theta \right)\, dt\,d\theta\\
& = \sum_{k=1}^{N_{\alpha}}\sum_{j=0}^{N_k}\int_{\mathbb{S}^{n-1}}\int_{\rn{+}} \left[ |\alpha_{k}(z_{-j}(x,\cdot) \theta_{-j}(x,\cdot))(\theta)|^{2} w_{j}\left( x,\cdot \right) w_{j}\left(x + t\theta, \cdot \right)\right]_{even}(\theta)\\
& \qquad \cdot f\left(x + t\theta \right)\, dt\,d\theta
\end{align*}
and
\begin{align*}
N_{\sigma,E,\alpha,reflect}f(x) & = \sum_{k=1}^{N_{\alpha}}\sum_{j_{1}=0}^{N_{k}}\sum_{j_{2}=0, j_{2} \neq j_{1}}^{N_k}\int_{\mathbb{S}^{n-1}}\int_{\mathbb{R}_{+}} |\alpha_{k}(z_{-j_{1}}, \theta_{-j_{1}})|^{2}\\
& \cdot w_{j_{1}}\left( x,\theta \right) w_{j_{2}}\left(z_{j_{2}-j_{1}}+ t\theta_{j_{2}-j_{1}}, \theta_{j_{2}-j_{1}}\right)f\left(z_{j_{2}-j_{1}}+ t\theta_{j_{2}-j_{1}}\right)\, dt\,d\theta.
\end{align*}
The notation $\left[ g(x,\cdot) \right]_{even}(\theta)$ is the even part of $g$ in the variable $\theta$, defined by $\left[ g(x,\cdot)\right]_{even}(\theta) = \frac{1}{2}\left[ g(x,\theta) + g(x,-\theta) \right]$. 

By Lemma 2 of \cite{xraygeneric} $N_{\sigma,E,\alpha, ballistic}$ is a classical pseudo differential operator of order $-1$ with principal symbol
\begin{equation}
a_{0}(x,\xi) = 2\pi \sum_{k=0}^{K}\sum_{j=0}^{N_{k}}\int_{\theta \in \mathbb{S}^{n-1}, \, \theta \cdot \xi = 0}|\alpha_{k}(z_{-j}, \theta_{-j})|^{2} \left| w_{j}\left( x,\theta \right)\right|^2 \,d\theta
\end{equation}
The bound on the number of reflections $N_{max}$ ensures that the integral kernel has a positive lower bound on the set of all covectors $(x,\xi)$ such that it is non vanishing at some $\theta \in \mathbb{S}^{n-1}$ normal to $\xi$. Clearly, $N_{\sigma,E,\alpha,ballistic}$ is also elliptic on the set $\mathcal{M}'$.

Simplifying $N_{\sigma,E,\alpha,reflect
$ for the Square \label{sec:normalsimplify}}
For the reflected part of the normal operator, our goal will be to make a change of variables so that $f(z_{j_{2}-j_{1}} + t\theta_{j_{2}-j_{1}})$ becomes $f(y)$, with the hope that what we obtain is either a weakly singular integral operator (i.e. smoothing of order $-1$) or an operator with $C_{0}^{\infty}$ Schwartz kernel. It turns out that the latter will hold. This technique is very much inspired by the kind of substitution used in \cite{inversesource, hubenthal}, and also in \cite{xraygeneric} for the non-Euclidean case. For now, we will still be working with the part of the operator that avoids broken rays with corner points.

Let $(x,\theta) \in \Omega \times \mathbb{S}^{1}$, suppose we have some smooth cutoff $\alpha$ on $\Gamma_{-}(E)$. By construction, all broken rays originating from the support of $\alpha$ have the same sequence of reflection signatures. Let $\{(h_{1},v_{1}), \ldots, (h_{N},v_{N})\}$ be the ordered set of all such pairs (see Figure \ref{fig:beam}). Let $z = z_{j_{2}-j_{1}}(x,\theta)$ (i.e. $z$ is the $j_{2}^{\mathrm{th}}$ reflection point on $\partial \Omega$ of the broken ray starting at $(z_{-j_{1}}(x,\theta), \theta_{-j_{1}}(x,\theta))$). Then $(h_{j_{2}}-h_{j_{1}}, v_{j_{2}}-v_{j_{1}})$ is the reflection signature from $x$ to $z$, and so we consider 
\begin{equation*}
\widetilde{z} := R_{h_{j_{2}}-h_{j_{1}},v_{j_{2}}-v_{j_{1}}}(z) =  (\widetilde{z}^{1}, \widetilde{z}^{2})
\end{equation*}
as the associated unfolded coordinates of $z$. Up to a rotation of $\Omega$, there are essentially two possibilities depending on whether $\widetilde{z}$ lies on a top or right edge of a reflected copy of the square. We will use $\theta$ to denote an angle value in radians and $\widehat{\theta} = (\cos{\theta}, \sin{\theta})$ to denote its associated direction vector. Furthermore, if $x \in \rn{2}$, we define $x^{\perp} = (-x^{2},x^{1})$. For simplicity of notation, we let $(l_{1},l_{2}) = (h_{j_{2}}-h_{j_{1}}, v_{j_{2}}-v_{j_{1}})$.

We have one of the following equations for $\widetilde{z}$ as a function of the starting point $x$ with direction $\theta$:
\begin{align}
\widetilde{z} & = (\widetilde{z}^{1}, l_{2}) = (x^{1} + (l_{2} - x^{2})\cot{\theta}, l_{2})\\
\widetilde{z} & = (l_{1}, \widetilde{z}^{2}) = (l_{1}, x^{2} + (l_{1} - x^{1})\tan{\theta}).
\end{align}

In the integral expression of the normal operator, we first make the substitution $\eta = S_{l_{1},l_{2}}(\theta)$, which is the reflected angle after applying the billiard map $j_{2}-j_{1}$ times to $(x+\tau_{-}(x,\widehat{\theta})\widehat{\theta},\, \widehat{\theta})$. Note that $|l_{1}|+|l_{2}| = j_{2} - j_{1}$. Obviously, the Jacobian determinant of this transformation is $1$. We also rewrite $z_{j_{2}-j_{1}}(x,\widehat{\theta}) = \pi_{1} \circ T^{j_{2}-j_{1}}(x+\tau_{-}(x,\widehat{\theta})\widehat{\theta}, \widehat{\theta})$ as the function $z(x,\eta)$. In particular, we may have either
\begin{align}
z(x,\eta) & = R_{l_{1},l_{2}}^{-1}\left(x^{1} + (l_{2} - x^{2})\cot\left(S_{l_{1},l_{2}}^{-1}(\eta)\right),\quad l_{2}\right)\label{eq:zxeta1}\\
& = \left((-1)^{l_{1}+1}l_{1} + \frac{1-(-1)^{l_{1}}}{2} + (-1)^{l_{1}}\left[ x^{1} + (l_{2} - x^{2})\cot\left(S_{l_{1},l_{2}}^{-1}(\eta)\right) \right], \quad \frac{1-(-1)^{l_{2}}}{2} \right) \notag
\end{align}
or
\begin{align}
z(x,\eta) & = R_{l_{1},l_{2}}^{-1}\left(l_{1}, \quad x^{2} + (l_{1} - x^{1})\tan\left(S_{l_{1},l_{2}}^{-1}(\eta)\right) \right) \label{eq:zxeta2}\\
& = \left(\frac{1-(-1)^{l_{1}}}{2}, \quad (-1)^{l_{2}+1}l_{2} + \frac{1-(-1)^{l_{2}}}{2} + (-1)^{l_{2}}\left[ x^{2} + (l_{1} - x^{1})\tan\left(S_{l_{1},l_{2}}^{-1}(\eta)\right) \right] \right).\notag
\end{align}

\begin{figure}
\centering
\def \svgwidth{0.7\columnwidth}

\caption{The basic setup for how we define coordinates in the integral formula for $N_{\sigma, E, \alpha}f$. Here $j_{2} =4$ and $j_{1}=2$. The original copy of $\Omega$ is in the center of the tiling, and $E$ consists of two disjoint open intervals of the boundary.\label{fig:substitution}}
\end{figure}
Thus we have an integrand involving $f(z(x,\eta) + t\widehat{\eta})$, where $\widehat{\eta} = (\cos{\eta},\sin{\eta})$. The next step is to make the substitution $y = z(x,\eta) + t\widehat{\eta}$ (see Figure \ref{fig:substitution}). We compute it's Jacobian determinant to be
\begin{align}
\left| \frac{\partial y}{\partial \eta \partial t} \right| & = |(-1)^{l_{2}}(l_{2}-x^{2})\csc{\eta} + t| = |(l_{2}-x^{2})\csc{\theta} + t| = |\widetilde{y}-\widetilde{z}|\left| \frac{l_{2}-x^{2}}{\widetilde{y}^{2} - \widetilde{z}^{2}} + 1 \right|\notag\\
& = |\widetilde{y}-\widetilde{z}|\left| \frac{\widetilde{y}^{2}-x^{2}}{\widetilde{y}^{2} - l_{2}} \right|
\end{align}
if $z(x,\eta)$ is given by (\ref{eq:zxeta1}). Similarly, we obtain
\begin{equation*}
\left| \frac{\partial y}{\partial \eta \partial t} \right| = |(-1)^{l_{1}}(l_{1} -x^{1})\sec{\eta} + t | = |\widetilde{y}-\widetilde{z}|\left| \frac{\widetilde{y}^{1}-x^{1}}{\widetilde{y}^{1} - l_{1}} \right|
\end{equation*}
when $z(x,\eta)$ is given by (\ref{eq:zxeta2}). Here we've used the fact that $\sec{\eta} = (-1)^{l_{1}}\sec{\theta}$ and $\csc{\eta} = (-1)^{l_{2}} \csc{\theta}$. In order to fully carry out the substitution in the integral, we need to write $z$ as a function of $x$ and $y$. We will need the auxiliary equation
\begin{equation}
(\widetilde{y} - \widetilde{z}) \cdot (\widetilde{z} - x)^{\perp} = 0,
\end{equation}
which is a consequence of the reflection law. In the case where $\widetilde{z}^{2}$ is undetermined, we have $\widetilde{z}^{1} = l_{1}$ and then
\begin{equation}
\widetilde{z}^{2} - \widetilde{y}^{2} = \frac{(\widetilde{y}^{2}-x^{2})(l_{1} - \widetilde{y}^{1})}{\widetilde{y}^{1} - x^{1}}.
\end{equation}
Similarly, if $\widetilde{z}^{1}$ is undetermined then
\begin{equation}
\widetilde{z}^{1} - \widetilde{y}^{1} = \frac{(\widetilde{y}^{1} - x^{1})(l_{2} - \widetilde{y}^{2})}{\widetilde{y}^{2} - x^{2}}.
\end{equation}

In the given case $\widetilde{z}^{1} = l_{1}$, the Jacobian determinant $\left| \frac{\partial y}{\partial \eta \partial t} \right|$ simplifies to
\begin{align*}
 |\widetilde{y}-\widetilde{z}|\left| \frac{\widetilde{y}^{1}-x^{1}}{\widetilde{y}^{1} - l_{1}} \right| & = \sqrt{ (\widetilde{y}^{1} - \widetilde{z}^{1})^{2} + (\widetilde{y}^{2} - x^{2})^{2} \frac{(l_{1} - \widetilde{y}^{1})^{2}}{\widetilde{y}^{1} - x^{1})^{2}}} \left| \frac{\widetilde{y}^{1}-x^{1}}{\widetilde{y}^{1} - l_{1}} \right| \\
 & = |\widetilde{y} - x|.
 \end{align*}
The same holds when $\widetilde{z}^{2} = l_{2}$. Conveniently, $|\widetilde{y}-x|$ is strictly positive for all $x,y \in \mathrm{supp}(f)$ so long as $l_{1}$ or $l_{2}$ is nonzero (i.e. $j_{2} - j_{1} \neq 0$). To see this, just note that for $(l_{1},l_{2}) \neq (0,0)$, we have $\widetilde{y} \notin \Omega$, and thus $|\widetilde{y} - x| \geq d(\mathrm{supp}(f), \partial \Omega) > 0$. Thus the reciprocal factor $\frac{1}{|\widetilde{y}-x|}$ resulting from the change of variables is smooth and bounded as a function of $y$ and $x$. Using again the fact that $\cos{\eta} = (-1)^{l_{1}}\cos{\theta}$, $\sin{\eta} = (-1)^{l_{2}}\sin{\theta}$ we have that
\begin{equation*}
\widehat{\eta} = ((-1)^{l_{1}}\cos{\theta},(-1)^{l_{2}}\sin{\theta}) = \frac{1}{|\widetilde{y}-x|}( (-1)^{l_{1}}(\widetilde{y}^{1}- x^{1}), (-1)^{l_{2}}(\widetilde{y}^{2} - x^{2})).
\end{equation*}
Altogether, we obtain that $N_{\sigma, E,\alpha, reflect}f(x)$ consists of a sum of terms of the form
\begin{equation}
\int_{\rn{2}} |\alpha_{k}(T^{-j_{2}}(y + \tau_{-}(y,\widehat{\eta})\widehat{\eta}, \widehat{\eta}))|^{2} w_{j_{1}}\left( x,\frac{\widetilde{y}-x}{|\widetilde{y}-x|} \right) w_{j_{2}}\left(y, \widehat{\eta}\right)f\left(y\right)\, \frac{dy}{|\widetilde{y} -x|}.\label{eq:normalreflectedterm}
\end{equation}

Note that one must be very careful in the above formulation in order to show that the integrand in (\ref{eq:normalreflectedterm}) is smooth where it is supported. Consider the case if $\alpha_{k}$ is non vanishing for a broken ray which starts at a corner point, but still none of the broken rays in the support of $\alpha$ contain another corner point after some positive number of reflections. Within the factor of (\ref{eq:normalreflectedterm}) given by
\begin{equation*}
|\alpha_{k}(T^{-j_{2}}(y + \tau_{-}(y,\widehat{\eta})\widehat{\eta}, \widehat{\eta}))|^{2},
\end{equation*}
we see that $T^{-j_{2}}(y + \tau_{-}(y,\widehat{\eta})\widehat{\eta}, \widehat{\eta})$ fails to be smooth for $(y, \eta)$ that are pulled back to this corner point. However, as previously discussed, the construction of $\alpha_{k}$ ensures that it is smooth on $\rn{2}\times \mathbb{S}^{1}$. Recall that $B = B\left( \left( \frac{1}{2}, \frac{1}{2} \right), \frac{\sqrt{2}}{2}\right)$ is the ball that circumscribes $\Omega$. By a possible rotation of $\Omega$, we may as well assume that $h_{j},v_{j}$ are all nonnegative. Clearly each sequence $\{h_{j}\}$, $\{v_{j}\}$ is also nondecreasing in this case. Next define the function $q_{j}(y, \eta)$ for $1 \leq j \leq N$ as the \textit{final} intersection point of the line $R_{h_{j},v_{j}}(y) + t \widehat{S_{h_{j},v_{j}}^{-1}(\eta)}$ with $\partial B$ for $t \leq 0$. We also define $q_{0}(y,\eta) = y + \tau_{-,\partial B}(y,\eta) \widehat{\eta}$ where $\tau_{-,\partial B}(y,\widehat{\eta})$ is the negative distance to $\partial B$ from $y$ in the direction $-\widehat{\eta}$, defined for $(y,\widehat{\eta}) \in B \times \mathbb{S}^{1}$. We can then replace $\alpha_{k}(T^{-j_{2}}(y + \tau_{-}(y,\widehat{\eta})\widehat{\eta}, \widehat{\eta}))$ with
\begin{equation}
\alpha_{k}(q_{j_{2}}(y,\widehat{\eta}), \, \widehat{S_{h_{j_{2}}, v_{j_{2}}}^{-1}(\eta)}). \label{eq:smoothalphakterm}
\end{equation}
Clearly, (\ref{eq:smoothalphakterm}) depends smoothly on $y, \eta$.

We observe that the definitions of $w_{j_{1}}, w_{j_{2}}$ also involve $\tau_{-}$, which is not smooth on $\Omega \times \mathbb{S}^{1}$. However, since $\sigma$ is compactly supported inside of $\Omega$ on some smooth subdomain, we can modify $\tau_{-}$ inside of $w_{j_{1}},w_{j_{2}}$ as necessary to be smooth without changing the integrals. In particular, we can use the functions $q_{j}$ to define the weight functions instead of the billiard map $T$ and boundary distance function $\tau_{-}$. Therefore, (\ref{eq:normalreflectedterm}) is a smoothing integral operator.

Incorporating Corners\label{sec:corners
}
Recall from the proof of Proposition \ref{thm:microlocalsquare} that by unfolding the broken rays, corner points posed no problem. This meant we didn't have to remove any covectors from $\mathcal{M}'$ whose corresponding broken rays passed through a corner point. It is thus important to also consider broken rays with corners for the normal operator so as to make $\mathcal{M}'$ as big as possible. However, for this we no longer have the option of path unfolding, so it will be necessary to treat reflections more directly.

While the corners of $\partial \Omega$ have no well-defined normal vector, we can make sense of a broken ray that touches a corner point by realizing it as a limit of broken rays that avoid the corner. This is described in detail in the 2-dimensional case in the work of Eskin in \cite{eskin}. Essentially, in 2-dimensions there are two reflection directions at a corner point that can be obtained as a limit of broken rays starting at some fixed point $x \in \Omega$ and with reflection point approaching the given corner. In higher dimensions, one can obtain a cone of possible reflection directions, which is thus a hypersurface. However, for the square (or even the $n$-cube), these limiting rays all conveniently coincide. To see this, let $x\in \Omega$ and let $c$ be a corner point. Define $\theta_{c}$ as the angle between $c-x$ and the horizontal axis. For $\theta$ close to $\theta_{c}$, the broken ray from $x$ in the direction $\widehat{\theta}$ will intersect twice near $c$ and return at an angle $\pi+\theta$ with the positive horizontal direction (i.e. it will return in the direction $-\widehat{\theta}$). Therefore, the limit of such rays shows that $\gamma_{x,\theta_{c}}$ unambiguously reflects back towards $x$. This is also consistent with what one expects from path unfolding.

The following simple lemma is useful in that it significantly limits the number of cases to consider of broken rays with corner points.
\begin{lemma}A regular broken ray starting from $E$ contains at most two corner points, and if it has two, then the first one is its starting point.\end{lemma}
\begin{proof}Suppose we have a broken ray $\gamma_{x_{0},\theta_{0}}$ with two distinct corner points. Since reflections from corners return in the opposite direction from the direction of incidence, any broken ray between them will repeat periodically. Thus, either one of the corner points lies in $E$, or there is a point along the broken ray between them that lies in $E$. But this implies the broken ray would have terminated before hitting both corners.\end{proof}

We will use $c \neq x_{0}$ to refer to a corner in the broken ray if it has one, and we will allow for the possibility that $x_{0}$ itself is a corner point. However, as previously discussed, $x_{0}$ being a corner point does not present any problem with regard to the smoothness of the integrands involved in the expansion of the localized normal operator (see the discussion following (\ref{eq:normalreflectedterm})). As before, let $K \Subset \Omega$ be the set on which we assume $f$ has support. 

So given our broken ray $\gamma_{x_{0},\theta_{0}}$, we assume it passes through a corner point $c \neq x_{0}$ at the $m^{\mathrm{th}}$ reflection, where $1 \leq m \leq N-1$, and $N-1$ is the total number of reflections of the curve. Choose a neighborhood $U$ consisting of $(x,\theta) \in \Gamma_{-}(E)$ that are sufficiently close to $(x_{0},\theta_{0})$ in the following sense. At the $m^{\mathrm{th}}$ reflection, most nearby broken rays to $\gamma_{x_{0},\theta_{0}}$ will undergo a reflection along a very short segment near the corner on which $f$ vanishes and $\sigma = 0$. In particular, such segments do not affect the weights $w_{j}$ and so we will be able to discard them. Thus, we choose $U$ small enough so that at the $m$th reflection, all nearby broken rays to $\gamma_{x_{0},\theta_{0}}$ either pass through the corner $c$ or hit close enough to the corner so as to reflect into a short path that contributes nothing to the integral. Note that for such broken rays from $U$ passing very near to the corner $c$ (but not actually touching it), after the $(m+1)^{\mathrm{th}}$ reflection they will be oriented in a direction opposite their respective directions during the $(m-1)^{\mathrm{th}}$ segment. We also choose $U$ small enough so as not to introduce any new corner points among the included broken rays.

Given such an open set $U$, we let $\mathbbm{1}_{U}(x,\theta)$ be a function on $\rn{2} \times \mathbb{S}^{1}$ which is constant on lines and satisfies
\begin{equation}
\mathbbm{1}_{U}(x,\theta) = \left\{ \begin{array}{cc}
1 & \textrm{ if $(\gamma_{x,\theta}(t), \dot{\gamma}_{x,\theta}(t)$ passes through $U$ and intersects the corner $c$,}\\
0 & \textrm{ otherwise }
\end{array}\right.
\end{equation}
Also let $\alpha(x,\theta)$ be a smooth cutoff function in $\rn{2} \times \mathbb{S}^{1}$ which vanishes outside the set of lines associated with $U$. We write the localized broken ray transform as
\begin{align}
I_{\sigma, E, \alpha}f(x,\theta) & = \sum_{j=0}^{N} \int_{\rn{+}}(1- \mathbbm{1}_{U}(x,\theta))\alpha(x,\theta)[w_{j}f](z_{j}(x,\theta) + t\theta_{j}(x,\theta), \theta_{j}(x,\theta))\,dt \notag\\
& + \sum_{j=0}^{N-1} \int_{\rn{+}}\mathbbm{1}_{U}(x,\theta)\alpha(x,\theta)[w_{j}f](z_{j}(x,\theta) + t\theta_{j}(x,\theta), \theta_{j}(x,\theta))\,dt.
\end{align}
We then have
\begin{align}
I_{\sigma, E, \alpha}^{*}g(x) & = \sum_{j=0}^{N} \int_{\mathbb{S}^{1}}[(1- \mathbbm{1}_{U})\alpha g](z_{-j}(x,\theta), \theta_{-j}(\theta))w_{j}(x,\theta)\,d\theta \notag\\
& + \sum_{j=0}^{N-1} \int_{\mathbb{S}^{1}}[\mathbbm{1}_{U}\alpha g](z_{-}(x,\theta), \theta_{-j}(x,\theta))w_{j}(x,\theta)\,d\theta.
\end{align}
Finally, the normal operator is given by
\begin{align}
I_{\sigma, E, \alpha}^{*}I_{\sigma, E, \alpha}f(x) & = \sum_{j_{1}=0}^{N}\sum_{j_{2}=0}^{N}\int_{\mathbb{S}^{1}}\int_{\rn{+}}[(1-\mathbbm{1}_{U})|\alpha|^{2}](z_{-j_{1}}(x,\theta),\theta_{-j_{1}}(x,\theta))w_{j_{1}}(x,\theta) \notag\\
& \quad \cdot [w_{j_{2}}f](z_{j_{2}-j_{1}}(x,\theta) + t\theta_{j_{2}-j_{1}}(x,\theta), \theta_{j_{2}-j_{1}}(x,\theta))\, dt \,d\theta \notag\\
& +  \sum_{j_{1}=0}^{N-1}\sum_{j_{2}=0}^{N-1}\int_{\mathbb{S}^{1}}\int_{\rn{+}}[\mathbbm{1}_{U}|\alpha|^{2}](z_{-j_{1}}(x,\theta),\theta_{-j_{1}}(x,\theta))w_{j_{1}}(x,\theta) \notag\\
& \quad \cdot [w_{j_{2}}f](z_{j_{2}-j_{1}}(x,\theta) + t\theta_{j_{2}-j_{1}}(x,\theta), \theta_{j_{2}-j_{1}}(x,\theta))\, dt \,d\theta.
\end{align}
Here we've used the fact that $(1-\mathbbm{1}_{U})^{2} = 1 - \mathbbm{1}_{U}$. Then break off the part with $j_{2} = j_{1}$ to obtain
\begin{align*}
N_{\sigma, E, \alpha, ballistic}f(x) & =  \sum_{j=0}^{N}\int_{\mathbb{S}^{1}}\int_{\rn{+}}[(1-\mathbbm{1}_{U})|\alpha|^{2}](z_{-j}(x,\theta),\theta_{-j}(x,\theta))w_{j}(x,\theta) \notag\\
& \quad \cdot [w_{j}f](x + \tau_{-}(x,\theta)\theta+ t\theta, \theta)\, dt \,d\theta \notag\\
& +  \sum_{j=0}^{N-1}\int_{\mathbb{S}^{1}}\int_{\rn{+}}[\mathbbm{1}_{U}|\alpha|^{2}](z_{-j}(x,\theta),\theta_{-j}(x,\theta))w_{j}(x,\theta) \notag\\
& \quad \cdot [w_{j}f](x + \tau_{-}(x,\theta)\theta + t\theta, \theta)\, dt \,d\theta.\notag.
\end{align*}
Now we have to be a bit careful in order to combine both summands. In the first summand, whenever $(z_{-m}(x,\theta), \theta_{-m}(x,\theta))$ is in the support of $(1-\mathbbm{1}_{U})\alpha^{2}$, we know that $x+\tau_{-}(x,\theta)\theta + t\theta$ is a line segment very near the corner $c$ where $f$ vanishes. Thus we can throw out the term involving $j = m$. Now for the terms with $j < m$, we may immediately combine the summands into one, thus eliminating the presence of $\mathbbm{1}_{U}$. That is, we have
\begin{align}
N_{\sigma, E, \alpha, ballistic}f(x) & = \sum_{j=0}^{m-1}\int_{\mathbb{S}^{1}}\int_{\rn{+}}|\alpha|^{2}(z_{-j}(x,\theta),\theta_{-j}(x,\theta))w_{j}(x,\theta) \notag\\
& \quad \cdot [w_{j}f](x + \tau_{-}(x,\theta)\theta+ t\theta, \theta)\, dt \,d\theta \notag\\
& + \sum_{j_{1}=m+1}^{N}\int_{\mathbb{S}^{1}}\int_{\rn{+}}[(1-\mathbbm{1}_{U})|\alpha|^{2}](z_{-j_{1}}(x,\theta),\theta_{-j_{1}}(x,\theta))w_{j_{1}}(x,\theta) \notag\\
& \quad \cdot [w_{j_{1}}f](x + \tau_{-}(x,\theta)\theta+ t\theta, \theta)\, dt \,d\theta \notag\\
& + \sum_{j_{2}=m}^{N-1}\int_{\mathbb{S}^{1}}\int_{\rn{+}}[\mathbbm{1}_{U}|\alpha|^{2}](z_{-j_{2}}(x,\theta),\theta_{-j_{2}}(x,\theta))w_{j_{2}}(x,\theta) \notag\\
& \quad \cdot [w_{j_{2}}f](x + \tau_{-}(x,\theta)\theta + t\theta, \theta)\, dt \,d\theta. \label{eq:normalballistic2}
\end{align}

